import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r,a,b as t}from"./chunks/M-S-SY3.DDtr6WYL.js";import{_ as o,o as s,c as n,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Copier les paramètres","description":"","frontmatter":{"source_hash":"68f7c3719c","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/copysettings.md","filePath":"fr/use/copysettings.md"}'),c={name:"fr/use/copysettings.md"};function l(d,e,u,m,v,h){return s(),n("div",null,[...e[0]||(e[0]=[p('<p>xDrip offre un moyen simple de copier les paramètres d&#39;un téléphone à un autre.</p><h3 id="show-settings-qr-code" tabindex="-1">Afficher le QR code des paramètres <a class="header-anchor" href="#show-settings-qr-code" aria-label="Permalink to &quot;Afficher le QR code des paramètres {#show-settings-qr-code}&quot;">​</a></h3><p>Affichage QR codes affiche un QR code contenant les paramètres de xDrip.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"> Affichage QR codes</p></div><div class="admonition xdrip"><p class="admonition-title">Partager les paramètres via le code QR</p><p> Utilisez les codes QR pour transférer les paramètres en utilisant Paramètres-&gt; Configuration Automatique</p></div><p>La clé de sécurité xDrip est utilisée pour la synchronisation xDrip ; si vous voulez seulement partager un code d&#39;abonné (difficile à recopier à la main), utilisez ce bouton.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  XDRIP+ CLÉS DE SÉCURITÉ SEULEMENT </div></p></div><p>Si vous avez utilisé des QR codes de personnalisation pour le xDrip de ce téléphone (G7, 1+, BlueJay, ...), vous pouvez les transférer directement vers un autre téléphone.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  EXPORT KEKS KEY TO ANOTHER PHONE </div></p></div><p>Les paramètres généraux et de collecte comprennent les paramètres généraux et ceux de votre source de données matérielle.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  AFFICHAGE GÉNÉRAL ET COLLECTION </div></p></div><p>Tous les paramètres comprennent l&#39;ensemble des réglages (sauf les alarmes : vous devez les recréer manuellement).</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  COPIER TOUS LES PARAMÈTRES </div></p></div><p>Vous obtenez un QR code que vous pouvez scanner avec Configuration automatique sur un autre téléphone.</p><img src="'+r+'" style="zoom:75%;"><h3 id="auto-configure" tabindex="-1">Configuration automatique <a class="header-anchor" href="#auto-configure" aria-label="Permalink to &quot;Configuration automatique {#auto-configure}&quot;">​</a></h3><p>Configuration automatique vous permet d&#39;importer des paramètres depuis un QR code.</p><p>Assurez-vous que le QR code que vous allez scanner provient d&#39;une source sûre.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configuration automatique</p></div><h4 id="camera" tabindex="-1">Caméra <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;Caméra {#camera}&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title">Caméra</p><p> Scannez un QR code avec votre mobile (recommandé)</p></div><p>Vous devez autoriser xDrip à accéder à l&#39;appareil photo du téléphone.</p><p>Vous pouvez ensuite scanner le QR code affiché sur un autre téléphone pour copier les paramètres que vous avez sélectionnés en l&#39;affichant, comme expliqué <a href="#show-settings-qr-code">ci-dessus</a>.</p><img src="'+a+'" style="zoom:75%;"><p>Les paramètres actuels seront remplacés ; une liste s&#39;affiche pour que vous la confirmiez.</p><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Importer les paramètres eulement des sources de confiance !<br>  Veuillez confirmer l&#39;importation les paramètres suivants :</p><p> paramètre1<br>  paramètre2<br>  paramètre3</p><p> Non     Oui</p></div><p>Un QR code <em>Copier tous les paramètres</em> ne contient pas les paramètres eux-mêmes : xDrip les télécharge une fois que vous avez confirmé. Depuis la version 2026.11.21, une confirmation vous est d&#39;abord demandée.</p><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Only import settings from sources you trust!<br>  Please confirm to download and import all settings from this code.</p></div><p>Vous devrez peut-être redémarrer votre téléphone pour appliquer les modifications.</p><h4 id="image-file" tabindex="-1">Fichier image <a class="header-anchor" href="#image-file" aria-label="Permalink to &quot;Fichier image {#image-file}&quot;">​</a></h4><p>Si l&#39;appareil photo de votre téléphone est de mauvaise qualité ou absent, vous pouvez charger le QR code depuis un fichier.</p><p>Vous devez d&#39;abord enregistrer dans vos images l&#39;image du QR code à scanner.</p><div class="admonition xdripitem"><p class="admonition-title">Fichier image</p><p> Vous pouvez enregistrer un code QR en tant que fichier image (comme .png ou .jpeg) sur votre mobile. Ensuite, utilisez cette option pour scanner le code QR du fichier enregistré.</p></div><p>Sélectionnez l&#39;image contenant le QR code.</p><img src="'+t+'" style="zoom:75%;"><p>Les paramètres actuels seront remplacés ; une liste s&#39;affiche pour que vous la confirmiez.</p><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Importer les paramètres eulement des sources de confiance !<br>  Veuillez confirmer l&#39;importation les paramètres suivants :</p><p> paramètre1<br>  paramètre2<br>  paramètre3</p><p> Non     Oui</p></div><p>Vous devrez peut-être redémarrer votre téléphone pour appliquer les modifications.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',40)])])}const b=o(c,[["render",l]]);export{_ as __pageData,b as default};
